export function matchTeachingSeed(subject:string,searchText:string):SubjectSeed|null{
 const normalize=(str:string)=>str.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const input=normalize(searchText);
 for(const item of rules){if(item.subject===subject&&item.pattern.test(input))return item.seed;}
 return null;
}
export function teachingSeedCount(){return rules.length;}
